world.crownMilitaryRoster:
crownMilitaryRoster(z) {
  if (this.peace) return;
  // Ironroot's relocation preserves the already assigned soldiery. New
  // distances must not recruit another native Wolf into a mounted slot.
  if (z.id === 'highlands' && z.appalachianVersion) return;
  const lineages = ['crownguard', 'goblin', 'orc', 'archer', 'ogre'];
  const label = (e) =>
    'Crown ' +
    (e.crownAncestry === 'crownguard' ? 'shield' : e.crownAncestry) +
    (e.ranged ? ' marksman' : ' guard');
  if (z.id === 'citadel') {
    const native = z.enemies
      .filter((e) => e.guard && e.form === 'normal' && !e.reinforcement)
      .sort((a, b) => this.idOrder(a, b));
    for (const [j, e] of native.entries()) {
      if (e.species !== 'crownguard') continue;
      e.crownTroop = true;
      e.crownAncestry = lineages[j % lineages.length];
      e.name = label(e);
    }
    return;
  }
  const anchors = {
    highlands: [
      [1050, 1360],
      [1850, 1160],
      [2950, 720],
    ],
    frontier: [
      [155, 615],
      [2600, 1650],
      [3000, 2700],
      [1700, 1250],
    ],
    crown: [
      [720, 900],
      [2580, 900],
      [3050, 2320],
      [3200, 2860],
    ],
  }[z.id];
  if (!anchors) return;
  const distance = (e) => {
    const x = e.home?.x,
      y = e.home?.y,
      previous = crownPostDistances.get(e);
    if (previous?.zone === z.id && previous.x === x && previous.y === y)
      return previous.distance;
    const value = Math.min(...anchors.map(([px, py]) => Math.hypot(x - px, y - py)));
    crownPostDistances.set(e, { zone: z.id, x, y, distance: value });
    return value;
  };
  // Existing Wolves nearest the Crown mint/convoy roads can be trained
  // mounts. Independent Wolf dens/strongholds and ordinary mountain
  // society are deliberately excluded; this creates no new population.
  if (z.id === 'highlands') {
    const riders = z.enemies
      .filter(
        (e) =>
          e.species === 'wolf' &&
          e.type === 'mob' &&
          e.form === 'normal' &&
          !e.guard &&
          !e.summon &&
          !e.mini &&
          !e.nightOnly &&
          !e.strongholdResident &&
          !e.site &&
          !e.neutral &&
          distance(e) < 1100,
      )
      .sort((a, b) => distance(a) - distance(b) || this.idOrder(a, b))
      .slice(0, 4);
    for (const [j, e] of riders.entries()) {
      e.mountedCrownRider = true;
      e.crownTroop = true;
      e.crownAncestry = 'wolf';
      e.name = j % 2 ? 'Crown direwolf mounted archer' : 'Crown direwolf lance patrol';
      e.forcedRole = j % 2 ? 'ranged' : 'melee';
      this.configureEnemy(e, j);
      // Military posts use the no-farm contract while retaining the
      // original Wolf HP, damage, level and patrol/quest identity.
      e.gold = 0;
      e.xp = 0;
    }
  }
  const quota = { highlands: 5, frontier: 10, crown: 12 }[z.id];
  const soldiers = z.enemies
    .filter(
      (e) =>
        e.type === 'mob' &&
        e.form === 'normal' &&
        !e.summon &&
        !e.captain &&
        !e.roomCaptain &&
        !e.fieldCaptain &&
        !e.nightOnly &&
        !e.neutral &&
        // Crown soldier posts remain Crown even when assigned to a named
        // redoubt. Do not turn local monster habitats into generic soldiery.
        (z.id === 'crown'
          ? e.species === 'crownguard'
          : !e.guard &&
            !e.mini &&
            !e.strongholdResident &&
            ['crownguard', 'goblin', 'orc', 'archer', 'ogre'].includes(e.species)) &&
        distance(e) < (z.id === 'crown' ? 1550 : 880),
    )
    .sort((a, b) => distance(a) - distance(b) || this.idOrder(a, b))
    .slice(0, quota);
  for (const [j, e] of soldiers.entries()) {
    e.crownTroop = true;
    e.crownAncestry = e.species === 'crownguard' ? lineages[j % lineages.length] : e.species;
    if (z.id === 'crown') {
      // Existing open-capital troops had all defaulted to archery;
      // half now screen the rest with shields without stat inflation.
      e.forcedRole = j % 2 === 0 ? 'melee' : 'ranged';
      this.configureEnemy(e, j);
    }
    e.name = label(e);
  }
}
// Sparse state heraldry is decorative and avoids road obstructions.

world.roadsideLanternLife:
roadsideLanternLife(z) {
  // Reconcile older unpublished dev.51 saves to the existing 21
  // public lanterns; the redundant fifteen-lamp pass is retired.
  if (z.props?.some((p) => p.roadLamp || String(p.id || '').startsWith('night-road-lamp-'))) {
    z.props = z.props.filter(
      (p) => !p.roadLamp && !String(p.id || '').startsWith('night-road-lamp-'),
    );
    delete z.roadLampVersion;
  }
  if (
    z.roadsideLanternVersion === 1 ||
    dungeonIds.includes(z.id) ||
    this.supplyRoom(z.id) ||
    this.sideDungeon(z.id)
  )
    return;
  const i = this.regionIndex(z.id),
    town = D.towns[i],
    minor = D.minors[i],
    special =
      {
        vale: [[1190, 760]],
        march: [
          [2120, 695],
          [1020, 530],
        ],
        highlands: [
          [1670, 1120],
          [2800, 700],
        ],
        frontier: [
          [1720, 1380],
          [2590, 1600],
          [2980, 2650],
        ],
        crown: [
          [2550, 900],
          [3030, 2310],
          [3210, 2830],
          [2600, 1370],
        ],
      }[z.id] || [],
    anchors = [town, minor, ...special],
    oldZone = this.s.zone;
  this.s.zone = z.id;
  try {
    z.props = z.props.filter((p) => !String(p.id || '').startsWith('public-lantern-'));
    let index = 0;
    const roads = z.roads?.flat() || [];
    for (const [x, y] of anchors) {
      if (index >= ({ vale: 3, march: 4, highlands: 4, frontier: 4, crown: 6 }[z.id] || 0))
        break;
      if (!roads.length) break;
      const center = roads.reduce(
        (best, p) => (!best || dist(p, { x, y }) < dist(best, { x, y }) ? p : best),
        null,
      );
      if (!center || dist(center, { x, y }) > 600) continue;
      let found = null;
      for (const radius of [65, 83, 100]) {
        for (let k = 0; k < 16; k++) {
          const a = (k * Math.PI) / 8,
            p = { x: center.x + Math.cos(a) * radius, y: center.y + Math.sin(a) * radius },
            shoulder = this.distanceToRoad(z, p);
          if (
            shoulder < 38 ||
            shoulder > 105 ||
            this.blocked(p.x, p.y, z.id, 10, true) ||
            z.npcs.some((n) => dist(n, p) < 83) ||
            z.nodes.some((n) => dist(n, p) < 72) ||
            z.buildings.some((b) => dist(b, p) < 105) ||
            z.props.some((q) => dist(q, p) < (q.r || 0) + 62) ||
            z.enemies.some((e) => e.hp > 0 && dist(e.home || e, p) < 90)
          )
            continue;
          found = p;
          break;
        }
        if (found) break;
      }
      if (!found) continue;
      z.props.push({
        id: 'public-lantern-' + z.id + '-' + index++,
        ...found,
        structure: 'roadside-lantern',
        r: 0,
        decorative: true,
        publicWorks: 'maintained-road-light',
      });
    }
    z.roadsideLanternVersion = 1;
  } finally {
    this.s.zone = oldZone;
  }
}

world.authoredPlaces:
authoredPlaces(z) {
  if (this.supplyRoom(z.id)) {
    this.treasuryInterior(z);
    this.treasuryGuardPopulation(z);
    this.combatPopulation(z);
    this.guardianPopulation(z);
    this.roomCaptainPopulation(z);
    return;
  }
  if (this.sideDungeon(z.id)) {
    this.combatPopulation(z);
    this.ordinaryMeleePopulation(z);
    this.ordinaryRangedPopulation(z);
    return;
  }
  this.harborLayout(z);
  this.repairMiniGuardianReachability(z);
  this.spaceQuestBoard(z);
  this.spaceMillhavenSupplier(z);
  this.combatPopulation(z);
  this.nightEnemyPopulation(z);
  if (dungeonIds.includes(z.id)) {
    this.dungeonWorkstation(z);
    this.decorateDungeon(z);
    this.abyssAviationProject(z);
    // Existing Ironroot v4 saves may already have the current dungeon
    // geometry version. Refurbish ONLY surviving/recorded native Wolf
    // slots as mounted guards, never summon or revive replacement Wolves.
    if (z.id === 'mine' && !this.peace) {
      const native = z.enemies
        .filter((e) => e.guard && e.form === 'normal' && !e.reinforcement)
        .sort((a, b) => this.idOrder(a, b));
      for (const [j, e] of native.entries()) {
        const post = R.dungeonGuardFormations.mine[j];
        if (!post?.mountedCrownRider || e.species !== 'wolf') continue;
        e.mountedCrownRider = true;
        e.crownTroop = true;
        e.crownAncestry = 'wolf';
        e.forcedRole = post.role;
        e.name = post.name;
        this.configureEnemy(e, j);
      }
    }
    for (const e of z.enemies) this.upgradeRingleader(e);
    this.guardianPopulation(z);
    this.guardianRewards(z);
    this.crownMilitaryRoster(z);
    return;
  }
  if (z.placesVersion !== 2) {
    z.npcs = z.npcs.filter((n) => !n.id.startsWith('landmark-'));
    const i = this.regionIndex(z.id);
    for (const [id, name, x, y] of R.sites[i]) {
      let n = z.npcs.find((n) => n.id === id);
      const data = {
        id,
        name,
        kind: 'landmark',
        ...this.safe(x, y, z.id),
        icon: /bridge|crossing/i.test(name)
          ? '🪵'
          : /camp|convoy|wagon/i.test(name)
            ? '🏕️'
            : '🏚️',
        ...(z.id === 'frontier' && id === 'checkpoint' ? { internalSite: true } : {}),
      };
      if (n) Object.assign(n, data);
      else z.npcs.push(data);
    }
    z.placesVersion = 2;
  }
  this.localSites(z);
  this.retireResourceMini(z);
  this.resourceDeposits(z);
  this.miniDungeons(z);
  this.repairMiniGuardianReachability(z);
  this.spreadOutdoorForces(z);
  this.alignLandmarks(z);
  this.sideInteriors(z);
  this.supplyInteriors(z);
  this.regionalAesthetics(z);
  this.worldLife(z);
  this.creatureStrongholds(z);
  this.frontierOccupationLayout(z);
  this.darkCrownLayout(z);
  this.ordinaryMeleePopulation(z);
  this.ordinaryRangedPopulation(z);
  this.guardianPopulation(z);
  this.summonPopulation(z);
  for (const e of z.enemies) this.upgradeRingleader(e);
  this.fieldCaptainPopulation(z);
  this.finalBossPopulation(z);
  this.regionalHandoffLife(z);
  this.greenwoodCountryLife(z);
  this.ironrootLivelihood(z);
  this.crownMilitaryRoster(z);
  this.regimeHeraldry(z);
  this.recoveryAndThermalLife(z);
  this.roadsideLanternLife(z);
  this.marchCoastalLayout(z);
  this.lanternShoreLayout(z);
  this.highlandsTributeLayout(z);
}

navigation.blocked:
blocked(x, y, zone = this.s.zone, radius = 15, terrainOnly = false, fort = null) {
  const i = this.regionIndex(zone),
    room = this.supplyRoom(zone),
    side = this.sideDungeon(zone),
    dungeon = dungeonIds.includes(zone),
    size = this.zoneSize(zone);
  if (
    !size ||
    x < 40 + radius ||
    y < 40 + radius ||
    x > size - 40 - radius ||
    y > size - 40 - radius
  )
    return true;
  if (room) {
    const architecture = R.treasuryArchitecture?.[zone];
    if (architecture) {
      const inside = (architecture.walkable || []).some((a) => {
        const [x1, x2, y1, y2] = a.bounds;
        return x > x1 + radius && x < x2 - radius && y > y1 + radius && y < y2 - radius;
      });
      if (!inside) return true;
      for (const w of architecture.partitions || []) {
        if (fort?.partitions.has(w.id)) continue;
        const hit =
          x > w.x1 - radius && x < w.x2 + radius && y > w.y1 - radius && y < w.y2 + radius;
        if (!hit) continue;
        const v = w.axis === 'x' ? x : y;
        if (!(w.gaps || []).some(([l, h]) => v > l + radius && v < h - radius)) return true;
      }
    } else
      for (const w of R.treasuryWalls?.[zone] || []) {
        if (fort?.partitions.has(w.id)) continue;
        const hit =
          x > w.x1 - radius && x < w.x2 + radius && y > w.y1 - radius && y < w.y2 + radius;
        if (!hit) continue;
        const v = w.axis === 'x' ? x : y;
        if (!(w.gaps || []).some(([l, h]) => v > l + radius && v < h - radius)) return true;
      }
  } else if (dungeon) {
    const architecture = R.dungeonArchitecture?.[zone];
    if (architecture) {
      const inside = (architecture.walkable || []).some((a) => {
        const [x1, x2, y1, y2] = a.bounds;
        return x > x1 + radius && x < x2 - radius && y > y1 + radius && y < y2 - radius;
      });
      if (!inside) return true;
      for (const w of architecture.partitions || []) {
        if (fort?.partitions.has(w.id)) continue;
        const hit =
          x > w.x1 - radius && x < w.x2 + radius && y > w.y1 - radius && y < w.y2 + radius;
        if (!hit) continue;
        const v = w.axis === 'x' ? x : y;
        if (!(w.gaps || []).some(([l, h]) => v > l + radius && v < h - radius)) return true;
      }
    } else {
      const [a, b, gaps] = R.dungeonWalls[zone];
      if (
        x > a - radius &&
        x < b + radius &&
        y > 120 &&
        y < 1260 &&
        !gaps.some(([l, h]) => y > l + radius && y < h - radius)
      )
        return true;
    }
  } else if (side) {
  } else {
    const {
      bounds: [, , c, e],
      gaps,
    } = R.barriers[i];
    const onInheritedDeck =
      zone === 'crown' &&
      this.s.zones[zone]?.crownInheritedDecks?.some(
        (d) =>
          x > d.x1 + radius && x < d.x2 - radius && y > d.y1 + radius && y < d.y2 - radius,
      );
    if (
      !onInheritedDeck &&
      y > c - radius &&
      y < e + radius &&
      !gaps.some(([l, h]) => y > l + radius && y < h - radius)
    ) {
      for (let at = y - radius; at <= y + radius + 0.01; at += Math.max(1, radius / 2)) {
        const [a, b] = R.channelBanks(i, at);
        if (x > a - radius && x < b + radius) return true;
      }
    }
  }
  if (!dungeon && !room && !side)
    for (const p of R.terrain[i])
      if (
        p.kind === 'rain-pools'
          ? R.rainPoolBlocked(p.pools, x, y, radius)
          : p.r
            ? // Reject obstacles far outside the circle's bounding box
              // without invoking a square root.
              (Math.abs(x - p.x) < p.r + radius &&
                Math.abs(y - p.y) < p.r + radius &&
                Math.hypot(x - p.x, y - p.y) < p.r + radius)
            : x > p.x1 - radius &&
              x < p.x2 + radius &&
              y > p.y1 - radius &&
              y < p.y2 + radius &&
              !(p.gaps || []).some(([l, h]) => y > l + radius && y < h - radius)
      )
        return true;
  if (!dungeon && !room && !side) {
    const harbor = R.harbors?.[D.regions[i]?.id];
    if (harbor) {
      const w = harbor.water,
        d = harbor.dock,
        onDock =
          x > d.x1 + radius && x < d.x2 - radius && y > d.y1 + radius && y < d.y2 - radius;
      if (!onDock && R.harborWaterBlocked(w, x, y, radius)) return true;
    }
  }
  const z = this.s.zones[zone];
  return (
    (!terrainOnly &&
      z?.props.some((p) => {
        if (fort?.props.has(p.id)) return false;
        // Zero-radius queries are the existing LOS/projectile contract.
        // Only positive-radius outdoor movement receives this first pass.
        const candidate =
          sceneryReady.has(z) &&
          radius > 0 &&
          !dungeon &&
          !room &&
          !side &&
          R.sceneryTraversal.radii[p.structure] !== undefined;
        const r = candidate
          ? Math.max(R.sceneryTraversal.radii[p.structure], p.decorative ? 0 : p.r)
          : p.decorative
            ? null
            : p.r;
        if (r === null || (candidate && R.sceneryTraversal.radii[p.structure] === 0))
          return false;
        const reach = r + radius,
          dx = x - p.x,
          dy = y - p.y;
        // A circle never overlaps a point outside its enclosing square.
        // Query current prop coordinates/radii every time: no stale cache.
        if (Number.isFinite(reach) &&
            (Math.abs(dx) >= reach || Math.abs(dy) >= reach))
          return false;
        const distance = Math.hypot(dx, dy);
        if (distance >= reach) return false;
        const body = candidate ? this.sceneryMovementRadius(p, z) : r;
        // Reuse the precise distance. Authored collision rules and
        // boundary handling remain unchanged.
        return body !== null && distance < body + radius;
      })) ||
    false
  );
}

navigation.line:
line(a, b) {
  const n = Math.ceil(dist(a, b) / 20);
  for (let i = 1; i < n; i++)
    if (
      this.blocked(a.x + ((b.x - a.x) * i) / n, a.y + ((b.y - a.y) * i) / n, this.s.zone, 0)
    )
      return false;
  return true;
}

navigation.clearSegment:
clearSegment(a, b, radius = 15, terrainOnly = false) {
  const n = Math.max(1, Math.ceil(dist(a, b) / 8));
  for (let j = 0; j <= n; j++)
    if (
      this.blocked(
        a.x + ((b.x - a.x) * j) / n,
        a.y + ((b.y - a.y) * j) / n,
        this.s.zone,
        radius,
        terrainOnly,
      )
    )
      return false;
  return true;
}

navigation.safe:
safe(x, y, zone = this.s.zone) {
  if (!this.blocked(x, y, zone)) return { x, y };
  for (let r = 30; r < 450; r += 30)
    for (let i = 0; i < 24; i++) {
      const a = (i * Math.PI) / 12,
        p = { x: x + Math.cos(a) * r, y: y + Math.sin(a) * r };
      if (!this.blocked(p.x, p.y, zone)) return p;
    }
  throw Error('No safe arrival');
}

navigation.route:
route(a, b, options = {}) {
  const terrainOnly = !!options.terrainOnly,
    target = this.safe(b.x, b.y),
    step = 50,
    size = this.zoneSize(),
    n = Math.ceil(size / step),
    point = (id) => ({ x: (id % n) * step + 25, y: Math.floor(id / n) * step + 25 });
  if (!options.road && this.clearSegment(a, target, 15, terrainOnly)) return [target];
  const nearby = (p) => {
    const out = [],
      cx = Math.floor(p.x / step),
      cy = Math.floor(p.y / step);
    for (let dx = -2; dx <= 2; dx++)
      for (let dy = -2; dy <= 2; dy++) {
        const x = cx + dx,
          y = cy + dy;
        if (x < 0 || y < 0 || x >= n || y >= n) continue;
        const id = y * n + x,
          q = point(id);
        if (
          !this.blocked(q.x, q.y, this.s.zone, 15, terrainOnly) &&
          this.clearSegment(p, q, 15, terrainOnly)
        )
          out.push(id);
      }
    return out.sort((x, y) => dist(point(x), p) - dist(point(y), p));
  };
  const starts = nearby(a),
    ends = nearby(target);
  if (!starts.length || !ends.length) return [];
  const search = (sources, goals) => {
    const queue = [...sources],
      parents = new Map(sources.map((id) => [id, null])),
      destinations = new Set(goals),
      valid = new Map();
    const free = (id) => {
      if (!valid.has(id)) {
        const p = point(id);
        valid.set(id, !this.blocked(p.x, p.y, this.s.zone, 15, terrainOnly));
      }
      return valid.get(id);
    };
    for (let at = 0; at < queue.length; at++) {
      const id = queue[at];
      if (destinations.has(id)) {
        let path = [target];
        for (let j = id; j !== null; j = parents.get(j)) path.push(point(j));
        path.reverse();
        if (options.road) {
          const compact = [{ x: a.x, y: a.y }];
          for (let j = 0; j < path.length; j++) {
            const prev = compact.at(-1),
              q = path[j],
              next = path[j + 1];
            if (
              next &&
              ((prev.x === q.x && q.x === next.x) || (prev.y === q.y && q.y === next.y))
            )
              continue;
            compact.push(q);
          }
          return compact;
        }
        const smooth = [];
        let current = a,
          j = 0;
        while (j < path.length) {
          let far = j;
          for (let k = j + 1; k < path.length; k++) {
            if (!this.clearSegment(current, path[k], 15, terrainOnly)) break;
            far = k;
          }
          smooth.push(path[far]);
          current = path[far];
          j = far + 1;
        }
        return smooth;
      }
      const x = id % n,
        y = Math.floor(id / n),
        from = point(id);
      for (const [dx, dy] of [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
      ]) {
        const xx = x + dx,
          yy = y + dy,
          j = yy * n + xx;
        if (
          xx < 0 ||
          yy < 0 ||
          xx >= n ||
          yy >= n ||
          parents.has(j) ||
          !free(j) ||
          !this.clearSegment(from, point(j), 15, terrainOnly)
        )
          continue;
        parents.set(j, id);
        queue.push(j);
      }
    }
    return [];
  };
  // Preserve all successful legacy routes and generated road geometry.
  // Only a false no-route retries with the other collision-validated
  // nearby anchors. Each seed and goal already has a clear end segment.
  const primary = search([starts[0]], [ends[0]]);
  return primary.length ? primary : search(starts, ends);
}

navigation.setSceneryTraversal:
setSceneryTraversal(z, ready = true) {
  if (ready) sceneryReady.add(z);
  else sceneryReady.delete(z);
}
